#include <iostream>
#include <set>
#include <string>
using namespace std;

int main() {
    string s;
    cin >> s;
    set<string> distinct;
    int n = s.size();
    for (int i = 0; i < n; ++i) {
        string shifted = s.substr(n - 1) + s.substr(0, n - 1);
        distinct.insert(shifted);
        s = shifted;
    }
    cout << distinct.size() << endl;
    return 0;
}
